function court(c,images,f,t){const q=span(t,649.2,653.5),swap=span(t,653.5,655);cover(c,images,f,'trialCourt',t,1.03+q*.025,-q*10,0);pic(c,images,f,'trialWitnessA',t,250+swap*1200,90,470,0);if(swap>0)pic(c,images,f,'trialWitnessB',t,-800+swap*1080,90,470,0);layer(c,f,'witness-rail',t,[0,410,960,130],(x,y,w,h)=>{const im=media(images,f,'trialCourt');if(im)c.drawImage(im,0,im.height*410/540,im.width,im.height*130/540,x,y,w,h);});vignette(c);}
function tablePass(c,images,f,t){const q=span(t,647.5,649.2);court(c,images,f,649.2);c.save();c.beginPath();c.rect(0,0,960,540-q*650);c.clip();c.translate(0,-q*650);writing(c,images,f,647.5);c.restore();layer(c,f,'table-edge',t,[0,450-q*650,960,130],(x,y,w,h)=>{wood(c,images,f,x,y,w,h);c.fillStyle='#0007';c.fillRect(x,y,w,h);});}
export function paintTrial(c,age,images,input={}){const f={...trialDefaults,...input},s=trialState(age,f),t=s.source;if(age<0||!f.trialEnabled)return s;c.save();c.canvas.sceneAssets=[];c.fillStyle='#000';c.fillRect(0,0,960,540);if(age===0){paintShelter(c,shelterDuration(f),images,f);c.restore();return s;}if(t<597.9){if(t>597.2)questioning(c,images,f,597.9);if(t<597.6){c.save();c.globalAlpha=1-span(t,597.15,597.6);incoming(c,images,f,t);c.restore();}fireWipe(c,images,f,t);}else if(t<607.2){questioning(c,images,f,t);if(t<598.2)fireWipe(c,images,f,t);}else if(t<609)shoulderPass(c,images,f,t);else if(t<610.8)questioning(c,images,f,t,true);else if(t<621.8)newspaper(c,images,f,t);else if(t<623){prison(c,images,f,623);c.save();const shift=span(t,621.8,623)*700;c.translate(0,-shift);c.beginPath();c.rect(0,0,960,540);c.clip();newspaper(c,images,f,621.8);c.restore();}else if(t<629.1)prison(c,images,f,t);else if(t<631.6)campPass(c,images,f,t);else if(t<635.35)camp(c,images,f,t);else if(t<641.45)overhead(c,images,f,t);else if(t<643)deskTilt(c,images,f,t);else if(t<647.5)writing(c,images,f,t);else if(t<649.2)tablePass(c,images,f,t);else court(c,images,f,t);if(f.trialIllustrationLabel&&t>=597.9)layer(c,f,'illustration-label',t,[18,505,924,18],(x,y)=>{c.fillStyle='#0009';c.fillRect(x-5,y-2,540,19);c.fillStyle='#e3e3dd';c.font='11px Arial';c.fillText('ILLUSTRATIVE RECONSTRUCTION · GENERATED PEOPLE / ENVIRONMENTS',x,y+11);});c.fillStyle='#000';c.fillRect(0,0,960,16);c.fillRect(0,524,960,16);c.restore();return s;}
